import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"内容搜索","description":"","frontmatter":{},"headers":[{"level":2,"title":"开始使用","slug":"开始使用","link":"#开始使用","children":[]},{"level":2,"title":"索引内容","slug":"索引内容","link":"#索引内容","children":[]},{"level":2,"title":"搜索方式","slug":"搜索方式","link":"#搜索方式","children":[]},{"level":2,"title":"清空与重建","slug":"清空与重建","link":"#清空与重建","children":[]},{"level":2,"title":"使用提示","slug":"使用提示","link":"#使用提示","children":[]}],"relativePath":"zh-CN/user-guide/content-search.md","filePath":"zh-CN/user-guide/content-search.md","lastUpdated":1791258065000}`),a={name:`zh-CN/user-guide/content-search.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="内容搜索" tabindex="-1">内容搜索 <a class="header-anchor" href="#内容搜索" aria-label="Permalink to “内容搜索”">​</a></h1><p>内容搜索插件可以检索本地文档中的正文，并在后台建立索引，与 Lertaro 原有的文件名搜索并行工作。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to “开始使用”">​</a></h2><p>打开<strong>设置 → 插件 → 内容搜索 → 配置</strong>，至少设置一个监测文件夹并保存。默认触发关键字为 <code>cs</code>：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cs 项目计划</span></span></code></pre></div><p>关键字后必须跟一个空格。如果 <code>cs</code> 与你的使用习惯冲突，可以在插件设置中改成其他关键字。</p><h2 id="索引内容" tabindex="-1">索引内容 <a class="header-anchor" href="#索引内容" aria-label="Permalink to “索引内容”">​</a></h2><ul><li><strong>监测文件夹</strong>：插件会向宿主索引服务注册配置的本地文件夹，通过 SDK 的索引目录枚举和防抖的目录变更通知完成首次及增量发现；每个文件夹都必须被宿主的本地驱动器索引或文件夹索引覆盖，否则枚举不到文件。支持 <code>%USERPROFILE%</code> 等环境变量，以及能够解析为真实文件夹的 <code>shell:Downloads</code> 等系统虚拟路径。</li><li><strong>文件后缀</strong>：默认包含 <code>txt</code>、<code>md</code>、<code>pdf</code>、<code>docx</code>、<code>docm</code>、<code>pptx</code>、<code>pptm</code>、<code>xlsx</code>、<code>xlsm</code> 和 <code>csv</code>，你可以按需要修改逗号分隔的列表。</li><li><strong>PDF 文件</strong>：会同时检索可提取的页面正文和已保存的可填写 PDF 表单字段值。</li><li><strong>文件大小</strong>：超过单个文件大小上限的文件会被跳过；内容索引还有独立的体积上限，设为 <code>0</code> 表示不限制。</li><li><strong>排除路径</strong>：输入以分号分隔的正则表达式来排除匹配的完整路径。文件夹路径匹配时，其内容也会被排除。</li></ul><p>只有成功提取出正文的文件才会参与搜索。没有对应文档提取器的二进制文件会被跳过，不会作为乱码文本写入索引。</p><p>即使配置的文件大小不限，正文提取仍有安全上限：Office ZIP 中每个解压后的条目最多 128 MiB，每个 Office/PDF 文档提取的文本最多 32 Mi 个字符。超过上限的文档会提取失败，不会只索引部分正文；单个文件的提取或写入失败会记入日志，后续文件仍会继续处理。</p><h2 id="搜索方式" tabindex="-1">搜索方式 <a class="header-anchor" href="#搜索方式" aria-label="Permalink to “搜索方式”">​</a></h2><p>在快速搜索窗口中输入 <code>cs</code>、空格和关键词即可搜索。结果会显示匹配文件的正文片段及所在文件夹，按下 <code>Enter</code> 可打开选中的文件。查询有结果时，在未选择类型筛选的情况下，完整搜索窗口中也会显示这些文件结果。</p><p>首次建立索引时，<code>cs</code> 占位结果会显示已索引文件数和剩余任务数。宿主监听器报告新增或变化的目录后，插件会在后台处理其中的文件，因此索引期间不会影响普通文件名搜索；索引稳定后不会再循环扫描文件系统。</p><p>支持单字、双字关键词，也支持将短词与长词组合查询。短词按字面子串匹配；条件允许时使用更长的关键词可提高查询速度。</p><p>仅在初次内容索引完成、以及每次主动重建后的首次完成时提示一次。复制或修改文件、保存设置和重启程序都不会再次弹出完成提示。达到索引体积上限时会单独警告；停止或暂停索引不算完成。</p><h2 id="清空与重建" tabindex="-1">清空与重建 <a class="header-anchor" href="#清空与重建" aria-label="Permalink to “清空与重建”">​</a></h2><p>内容搜索设置中提供两个不同的操作：</p><ul><li><strong>清空索引</strong>：删除内容索引，但不会重新扫描监测文件夹。</li><li><strong>重建索引</strong>：删除内容索引，然后重新扫描所有监测文件夹。</li></ul><p>这两个操作只影响内容搜索索引，不会删除 Lertaro 的普通文件名索引。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li>如果文件没有出现在结果中，请检查它所在的文件夹、后缀、排除规则和大小上限。</li><li>修改监测文件夹或索引规则后，请保存设置并等待后台扫描完成。</li><li>修改规则后如果希望重新提取已有文件，请使用<strong>重建索引</strong>。</li></ul>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};